import datetime
import time
from taf.ul.sc import perf
from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.tc import tc_helpers
from taf.ul.sc.perf.testline import device_helpers
from taf.ul.sc.perf.post.interfaces.post_process import PostProcess

_procedure_name = 'DB->string properties->test procedure name'
_test_case_name = 'DB->string properties->test case name'
_tester_username = 'DB->string properties->tester username'
_test_line_owner = 'DB->string properties->test line owner'
_test_line = 'DB->string properties->test line'
_test_line_type = 'DB->string properties->test line type'
_test_line_maintainers = 'DB->string properties->test line maintainers'
_lab_location = 'DB->string properties->lab location'
_execution_date = 'DB->string properties->execution date'
_start_test_timestamp = 'DB->integer properties->start test timestamp'
_stop_test_timestamp = 'DB->integer properties->stop test timestamp'
_scenario_duration = 'DB->integer properties->scenario duration'
_scenario_duration_measured = 'DB->integer properties->scenario duration measured'
_bts_uptime_before_test = 'DB->integer properties->device:{}->type:uptime->bts info before test'
_timestamp_before_test = 'DB->integer properties->device:{}->type:timestamp->bts info before test'
_bts_uptime_after_test = 'DB->integer properties->device:{}->type:uptime->bts info after test'
_timestamp_after_test = 'DB->integer properties->device:{}->type:timestamp->bts info after test'
_bts_nr_of_cells = 'DB->integer properties->device:{}->bts nr of cells'
_tti_stats = 'DB->integer properties->device:{}->cell:{}->sample id:{}->direction:{}->type:tti statistic->{}'
_ue_build = 'DB->string properties->ue build'
_ue_type = 'DB->string properties->ue type'
_core_build = 'DB->string properties->core build'
_bts_build = 'DB->string properties->bts build'
_bts_release = 'DB->string properties->bts release'
_bts_cells_bandwidths = 'DB->string properties->device:{}->bts cells bandwidths'
_bts_used_rrhs = 'DB->string properties->bts used rrhs'
_bts_hw_code = 'DB->string properties->device:{}->bts hardware code'
_bts_modules_serials = 'DB->string properties->device:{}->bts modules serials'
_test_status = 'DB->enumerated properties->status'
_valid_run = 'DB->boolean properties->valid run'
_permalink = 'DB->permalink'
_device_type = 'DB->device_type'  # need to change to eg. teb_view
_logs_url = 'DB->string properties->logs url'
_validation_url = 'DB->string properties->validation url'
_test_id = 'DB->id'
_coop_test_hierarchy = 'DB->string properties->coop test hierarchy'
_coop_business_line = 'DB->string properties->coop business line'
_coop_product = 'DB->string properties->coop product'


def add_execution_date():
    now = datetime.datetime.now()
    now_str = now.strftime("%Y-%m-%d %H:%M:%S")
    tc.add_stats(stats={_execution_date: now_str})


def add_start_test_timestamp():
    now = int(time.time())
    tc.add_stats(stats={_start_test_timestamp: now})


def add_stop_test_timestamp():
    now = int(time.time())
    tc.add_stats(stats={_stop_test_timestamp: now})


def add_scenario_duration():
    tc.add_stats(stats={_scenario_duration: tc.run_params['duration']})


def add_measured_scenario_duration():
    measured_duration = tc.stop_test_timestamp - tc.start_test_timestamp
    tc.add_stats(stats={_scenario_duration_measured: measured_duration})


def add_bts_uptime_before_test(bts_uptime, device_name):
    tc.add_stats(stats={
        _bts_uptime_before_test.format(device_name): bts_uptime,
        _timestamp_before_test.format(device_name): int(time.time())})


def add_bts_uptime_after_test(bts_uptime, device_name):
    tc.add_stats(stats={
        _bts_uptime_after_test.format(device_name): bts_uptime,
        _timestamp_after_test.format(device_name): int(time.time())})


def add_default_teb_values(default_values=None):
    if not default_values:
        default_values = tc.run_params['add_results_to_database']['default_values']

    stats = {
        _test_status: default_values['status'],
        _valid_run: default_values['valid_run']
    }
    tc.add_stats(stats=stats)


def add_required_parameters(device_type='Flexi'):
    permalink = PostProcess.generate_database_permalink(execution_date=tc.execution_date,
                                                        test_line_name=tc.test_line_name)
    stats = {
        'DB->object': "test execution",
        _permalink: permalink,
        _device_type: device_type,

    }
    tc.add_stats(stats=stats)


def add_bts_version(bts_sw_version, bts_release):
    stats = {
        _bts_build: bts_sw_version,
        _bts_release: bts_release
    }
    tc.add_stats(stats=stats)


def add_ue_version(ue_sw_version, ue_type):
    stats = {
        _ue_build: ue_sw_version,
        _ue_type: ue_type
    }
    tc.add_stats(stats=stats)


def add_core_version(core_sw_version):
    stats = {
        _core_build: core_sw_version,
    }
    tc.add_stats(stats=stats)


def add_tester_user_name(tester_username=None):
    if not tester_username:
        tester_username = tc_helpers.get_tester_username()
    if tester_username:
        tc.add_stats(stats={_tester_username: tester_username})


def add_procedure_name(procedure_name=None):
    if not procedure_name:
        procedure_name = tc.run_params['procedure_name']
    tc.add_stats(stats={_procedure_name: procedure_name})


def add_test_case_name(test_case_name=None):
    if not test_case_name:
        test_case_name = tc.test_case_name
    tc.add_stats(stats={_test_case_name: test_case_name})


def add_test_line(test_line=None):
    if not test_line:
        test_line = perf.tl.name
    tc.add_stats(stats={_test_line: test_line})


def add_test_line_owner(owner=None):
    if not owner:
        owner = perf.tl.owner
    tc.add_stats(stats={_test_line_owner: owner})


def add_test_line_type(test_line_type=None):
    if not test_line_type:
        test_line_type = perf.tl.tl_type
    tc.add_stats(stats={_test_line_type: test_line_type})


def add_test_line_maintainers(test_line_maintainers=None):
    if not test_line_maintainers:
        test_line_maintainers = ";".join(perf.tl.maintainers)
    tc.add_stats(stats={_test_line_maintainers: test_line_maintainers})


def add_lab_location(lab_location=None):
    if not lab_location:
        lab_location = device_helpers.get_test_line_location()

    if lab_location:
        tc.add_stats(stats={_lab_location: lab_location})


def add_coop_test_case_info(coop_params=None):
    """

    :param coop_params: dict in format {'business_line': value,
                                        'product'" value,
                                        'test_hierarchy': value}
    :return:
    """
    if not coop_params:
        coop_params = {'business_line': tc.run_params['add_results_to_coop']['business_line'],
                       'product': tc.run_params['add_results_to_coop']['product'],
                       'test_hierarchy': tc.run_params['add_results_to_coop']['test_hierarchy']
                       }

    tc.add_stats(stats={_coop_business_line: coop_params['business_line'],
                        _coop_product: coop_params['product'],
                        _coop_test_hierarchy: coop_params['test_hierarchy']})


def add_bts_cells_info(device_name=None, cells_bandwidths=None, nr_of_cells=None):
    if device_name:
        if cells_bandwidths:
            tc.add_stats(stats={_bts_cells_bandwidths.format(device_name): cells_bandwidths})
        if nr_of_cells:
            tc.add_stats(stats={_bts_nr_of_cells.format(device_name): nr_of_cells})


def add_bts_used_rrhs(bts_used_rrhs):
    if bts_used_rrhs:
        tc.add_stats(stats={_bts_used_rrhs: bts_used_rrhs})


def add_bts_hw_info(device_name=None, bts_hw_code=None, bts_modules=None):
    if device_name:
        if bts_hw_code:
            tc.add_stats(stats={_bts_hw_code.format(device_name): bts_hw_code})
        if bts_modules:
            tc.add_stats(stats={_bts_modules_serials.format(device_name): bts_modules})


def add_tti_cells_stats(device_name, tti_stats, sample_id=1):
    for cell_id in tti_stats:
        for direction in tti_stats[cell_id]:
            tc.add_stats(stats={_tti_stats.format(device_name, cell_id, sample_id, direction, 'Throughput'): tti_stats[
                cell_id][direction].throughput})
            tc.add_stats(stats={_tti_stats.format(device_name, cell_id, sample_id, direction, 'Users amount'): tti_stats[
                cell_id][direction].users_amount})
            tc.add_stats(stats={_tti_stats.format(device_name, cell_id, sample_id, direction, 'Max TBs amount'): tti_stats[
                cell_id][direction].counter['max_tb1']})
            tc.add_stats(stats={_tti_stats.format(device_name, cell_id, sample_id, direction, 'UEs in max TBs'): tti_stats[
                cell_id][direction].counter['max_ues_fd1']})
            tc.add_stats(stats={_tti_stats.format(device_name, cell_id, sample_id, direction, 'Max UEs amount'): tti_stats[
                cell_id][direction].counter['max_ues_fd2']})
            tc.add_stats(stats={_tti_stats.format(device_name, cell_id, sample_id, direction, 'TBs in max UEs'): tti_stats[
                cell_id][direction].counter['max_tb2']})
